def tool(text):
    import re
    # Find sentences containing 'Negev' and keywords indicating military action
    pattern = re.compile(r'[^.]*\bNegev\b[^.]*\b(operation|military|engagement|combat|attack|logistics|casualty)\b[^.]*\.', re.IGNORECASE)
    matches = pattern.findall(text)
    return "\n".join(matches)

